/**底部控制
 * 
 */

cc.Class({
    extends: require("LMSlots_Bottom_Base"),
    properties: {
    },

    //点击停止
    OnClickStop:function(){
        if(cc.vv.gameData.isBonusGame()){
            let slots = cc.vv.gameData.getBonusControl()
            slots.StopMove()
        }else{
            let slots = cc.vv.gameData.GetSlotsScript()
            slots.StopMove()
        }
    },

    OnClickAddBet:function(){
        this._super()
        Global.NmedusaGameControl.collectBonusControl.updataCollectState()
    },

    //点击减注
    OnClickMinusBet:function(){
        this._super()
        Global.NmedusaGameControl.collectBonusControl.updataCollectState()
    },

    //点击max
    OnClickMaxBet:function(){
        this._super()
        Global.NmedusaGameControl.collectBonusControl.updataCollectState()
    },

    showTotalBet(isShow){
        cc.find("totalBetBg", this.node).active = isShow
    },
});
