
/**
 * 卷轴控制单元
 */
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    //设置结果
    //[{sid:*,data:*}...]
    SetResult: function (val) {
        this._super(val)
        //第一列和最后一列只有三个图标；所以删除一个无用的多余图标
        if (this._reelIdx == 0 || this._reelIdx == 4) {
            this._originResult.pop()
            this._result.pop()
        }
    },

    //播放加速动画
    playAntiAnimation() {
        let isPlayAniti = false
        let cfg = cc.vv.gameData.getGameCfg()
        let isFree = cc.vv.gameData.isFreeGame()
        if (cfg.reelStateInfo && cfg.reelStateInfo[0]) {
            for (let info of this._reelState) {
                if (info.isAnt && info.antiNode) {
                    if (isFree && info.freeNode) {
                        this.ShowAntiEffect(true, info.freeNode)
                    } else {
                        this.ShowAntiEffect(true, info.antiNode)
                    }
                    cc.vv.AudioManager.playEff(info.path, info.antSound, true);
                    //考虑到加速倍率
                    let cfgAntSpeed = info.antSpeed
                    if (cfgAntSpeed) {
                        cfgAntSpeed = cfgAntSpeed * this.GetTimeScale()
                    }
                    this._speed = cfgAntSpeed ? cfgAntSpeed : this._speed
                    isPlayAniti = true
                }
            }
        }
        return isPlayAniti
    },


    //显示免费游戏加速效果
    //加速框的显示
    ShowAntiEffect: function (bShow, name) {
        if (bShow === false) {
            let cfg = cc.vv.gameData.getGameCfg()
            if (cfg.reelStateInfo) {
                for (let info of cfg.reelStateInfo) {
                    let node = cc.find("mask/" + info.antiNode, this.node)
                    if (node && node.active) {
                        node.active = false
                        if (this._stopRightNow) {
                            cc.vv.AudioManager.stopEffectByName(info.antSound);
                        }
                    }
                    let nodeFree = cc.find("mask/" + info.freeNode, this.node)
                    if (nodeFree && nodeFree.active) {
                        nodeFree.active = false
                        if (this._stopRightNow) {
                            cc.vv.AudioManager.stopEffectByName(info.antSound);
                        }
                    }
                }
            }
        } 
        if (bShow === true) {
            let node = cc.find("mask/" + name, this.node)
            if (node) {
                node.active = true

            }
            else {
                console.log(">>>> 未找到加速节点：mask/node_anti");
            }
        }
    },
});
