let freeGameCountAnimation= {
    [10]:{[1]:{pop:"animation1",show:"animation1_1"},[2]:{pop:"animation4",show:"animation4_4"},[3]:{pop:"animation7",show:"animation7_7"}},
    [20]:{[1]:{pop:"animation2",show:"animation2_2"},[2]:{pop:"animation5",show:"animation5_5"},[3]:{pop:"animation8",show:"animation8_8"}}, 
    [30]:{[1]:{pop:"animation3",show:"animation3_3"},[2]:{pop:"animation6",show:"animation6_6"},[3]:{pop:"animation9",show:"animation9_9"}}, 
}

cc.Class({
    extends: cc.Component,

    properties: {
        logoMeidusha: {
            default: null,        // The default value will be used only when the component attaching
            type: cc.Node, // optional, default is typeof default
        },
        _popup:null,
        _snakeSpine:null,
        _meidushaSpine:null,
        _popBonus:null,

        _cfg:null,
        collectButton:{
            default:null,
            type:cc.Node
        },
        jpCoinLable:{
            default:null,
            type:cc.Node
        },
        _startAddFreeWinCoin:false,
        jpLabelBg:{
            default:[],
            type:cc.Node
        },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {

    },

    Init() {
        this._cfg = cc.vv.gameData.getGameCfg()
        this._popup = cc.find("popup", this.node);
        this._popup.active = false;
        this._snakeSpine = cc.find("snake", this.node);
        this._snakeSpine.active = false;
        this._meidushaSpine = cc.find("meidusha", this.node);
        this._meidushaSpine.active = false;
        this._popBonus = cc.find("popup/popbonus", this.node);
        this._popBonus.active = false;
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },


    //显示免费游戏次数
    async showFreeGameTimes(num,type){   //type :  1 普通免费 2免费中免费  3superbonus免费
        return new Promise(async (sucess, failed)=>{
            if(type != 2){
                Global.SlotsSoundMgr.stopBgm();
            }
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.free_dialog_start_show)
            this._popup.active = true;
            let show_popup = this._popup.getChildByName("show_free_games_time");
            show_popup.active = true;
            show_popup.setScale(0.9);
            
            let spine = show_popup.getChildByName("spine");
            spine.getComponent(sp.Skeleton).setAnimation(0,freeGameCountAnimation[num][type].pop,false);
            spine.getComponent(sp.Skeleton).setCompleteListener(()=>{
                spine.getComponent(sp.Skeleton).setCompleteListener(null)
                spine.getComponent(sp.Skeleton).setAnimation(0,freeGameCountAnimation[num][type].show,true);
            });
            let startBtn = show_popup.getChildByName("start");
            let func = ()=>{
                startBtn.getComponent(cc.Button).interactable = false
                show_popup.runAction(cc.sequence(cc.scaleTo(0.4, 0.3).easing(cc.easeBackIn()),
                    cc.callFunc(()=>{
                        this._popup.active = false;
                        show_popup.active = false;
                        sucess();
                    })));
            }
            if(type == 2){
                startBtn.active = false;
                await this.awaitTime(2);
                func();
            } else {
                startBtn.active = true;
                startBtn.setScale(0);
                startBtn.runAction(cc.scaleTo(0.7, 1).easing(cc.easeBackOut()));
                await this.awaitTime(0.5);
                startBtn.getComponent(cc.Button).interactable = true
                startBtn.off("click");
                cc.vv.gameData.checkAutoPlay(startBtn, func);
                startBtn.on("click", ()=>{
                    startBtn.stopAllActions();
                    func();
                });
            }
        });
    },


     //显示free赢钱
    showFreeGameWinner(num){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.free_dialog_collect_show)
            this._popup.active = true;
            let show_popup = this._popup.getChildByName("show_free_games_win");
            show_popup.active = true;
            show_popup.setScale(0.9);
            let spine = show_popup.getChildByName("spine");
            spine.getComponent(sp.Skeleton).setAnimation(0,"animation10",false);
            spine.getComponent(sp.Skeleton).setCompleteListener(()=>{
                spine.getComponent(sp.Skeleton).setCompleteListener(null)
                spine.getComponent(sp.Skeleton).setAnimation(0,"animation10_10",true);
            });
            let startBtn = show_popup.getChildByName("start");
            startBtn.setScale(0);
            startBtn.runAction(cc.scaleTo(0.7, 1).easing(cc.easeBackOut()));

            let showLable = cc.find("lable", show_popup);
            showLable.setScale(0);
            showLable.runAction(cc.scaleTo(0.7, 1).easing(cc.easeBackOut()));
            let coinLable = cc.find("lable/coin", show_popup);
            coinLable.getComponent(cc.Label).string = "";
            await this.awaitTime(0.2);
            startBtn.runAction(cc.scaleTo(0.6, 1).easing(cc.easeBackOut()));
            //金币滚动
            this._startAddFreeWinCoin = true
            Global.doRoallNumEff(coinLable,0,num,2,()=>{
                this._startAddFreeWinCoin = false
            },null,0,true);
            startBtn.getComponent(cc.Button).interactable = true
            startBtn.off("click");
            let func = ()=>{
                if(this._startAddFreeWinCoin){
                    this._startAddFreeWinCoin = false
                    coinLable.stopAllActions()
                    let winCoinLabel = coinLable.getComponent(cc.Label)
                    winCoinLabel.string = Global.FormatNumToComma(num)
                    return
                }
                startBtn.getComponent(cc.Button).interactable = false
                show_popup.runAction(cc.sequence(cc.scaleTo(0.4, 0.3).easing(cc.easeBackIn()),
                    cc.callFunc(()=>{
                        this._popup.active = false;
                        show_popup.active = false;
                        sucess();
                    })));
            }
            cc.vv.gameData.checkAutoPlay(startBtn, func);
            startBtn.on("click", ()=>{
                startBtn.stopAllActions();
                func();
            });  
        });
    },

     //显示jackpot赢钱
     showJackpotWinCoin(type,mult,coin){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.jp_dialog_start_show)
            this._popup.active = true;
            let show_popup = this._popup.getChildByName("show_jackpot_winCoin");
            show_popup.active = true;
            show_popup.setScale(0.9);
            let spine = show_popup.getChildByName("jp_tc_01");
            let multRoot = show_popup.getChildByName("multRoot")
            for (let i = 0; i < multRoot.children.length; i++) {
                const element = multRoot.children[i];
                element.active = false
            }
            if(mult > 1){
                let multNode = cc.find("x"+mult,multRoot)
                if(multNode){
                    multNode.active = true
                }
            }
            for (let i = 0; i < this.jpLabelBg.length; i++) {
                const element = this.jpLabelBg[i];
                if((type - 1) === i){
                    element.active = true
                }else{
                    element.active = false
                }
            }
            let name = ""
            switch (type) {
                case 1:{
                    name = "animation_mini_"
                }break;
                case 2:{
                    name = "animation_mlnor_"
                }break;
                case 3:{
                    name = "animation_major_"
                }break;
                case 4:{
                    name = "animation_grand_"
                }break;
                case 5:{
                    name = "animation_maxl_"
                }break;
            }
            spine.getComponent(sp.Skeleton).setAnimation(0,name+1,false);
            spine.getComponent(sp.Skeleton).addAnimation(0,name+2,true);

            this._startAddFreeWinCoin = true
            Global.doRoallNumEff(this.jpCoinLable,Math.floor(coin*0.1),coin,2.5,()=>{
                this._startAddFreeWinCoin = false
            },null,0,true);

            await cc.vv.gameData.awaitTime(2.6);
            this.collectButton.getComponent(cc.Button).interactable = true
            this.collectButton.off("click");
            let func = ()=>{
                if(this._startAddFreeWinCoin){
                    this._startAddFreeWinCoin = false
                    this.jpCoinLable.stopAllActions()
                    let winCoinLabel = this.jpCoinLable.getComponent(cc.Label)
                    winCoinLabel.string = Global.FormatNumToComma(coin)
                    return
                }
                this.collectButton.getComponent(cc.Button).interactable = false
                cc.tween(show_popup).to(0.3,{scale:0}).call(()=>{
                    this._popup.active = false;
                    show_popup.active = false;
                    sucess();
                }).start()
            }
            cc.vv.gameData.checkAutoPlay(this.collectButton, func);
            this.collectButton.on("click", ()=>{
                this.collectButton.stopAllActions();
                func();
            });  
        });
    },


    playMedusaAnimation(callBack){
        return new Promise(async (sucess,failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.act1)
            this._meidushaSpine.active = true;
            this.logoMeidusha.active = false
            let animation = this._meidushaSpine.getComponent(sp.Skeleton);
            animation.setAnimation(0,"idle3",false)
            animation.setCompleteListener(()=>{
                this._meidushaSpine.active = false;
                sucess()
            });
            await this.awaitTime(1.5)
            this.logoMeidusha.active = true
            if(callBack){
                callBack()
            }
        })

    },
    async playSnakeAnimation(){
        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.act2)
        this._snakeSpine.active = true;
        let animation = this._snakeSpine.getComponent(sp.Skeleton);
        animation.setAnimation(0,"animation",false)
        animation.setCompleteListener(()=>{
            this._snakeSpine.active = false;
        });
    },
    async playPopBonus(){
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.respin_dialog_start_show)
        this._popup.active = true;
        this._popBonus.active = true;
        let animation = this._popBonus.getComponent(sp.Skeleton);
        animation.setAnimation(0,"animation",false)
        animation.setCompleteListener(()=>{
            this._popBonus.active = false;
            this._popup.active = false;
        });
    },
});
