/**
 * 符号控制
 */
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _bonusIndex:0,
    },


    //idx:符号的序号，即在reel中的序号，0开始
    Init:function(idx,node){
        this._topAniNode = node
        this.SetSymbolIdx(idx);
        this.ShowFristRandomSymbol()
    },

    setBonusIndex(index){
        this._bonusIndex = index
    },

    //第一次进入游戏随机图标
    ShowFristRandomSymbol:function(){  
        let randMult = [0.5,1,2,3,4,10,20];
        let randomSymbols = [4,5,6,7,8,9,10,11,12]
        let multIndex = Global.random(1,randMult.length)
        let mult = randMult[multIndex-1]
        let coin = cc.vv.gameData.GetTotalBet()*mult

        let randIdx = Global.random(1,randomSymbols.length)
        let randVal = randomSymbols[randIdx-1]
        this.ShowById(randVal,coin)
    },

    //显示随机符号
    ShowRandomSymbol:function(){  //已重写
        let randMult = [0.5,1,2,3,4,10,20];
        let randomSymbols = [1,2,4,5,6,7,8,9,10,11,12,21,22,23,24,25,26,27,28]
        let multIndex = Global.random(1,randMult.length)
        let mult = randMult[multIndex-1]
        let coin = cc.vv.gameData.GetTotalBet()*mult

        let randIdx = Global.random(1,randomSymbols.length)
        let randVal = randomSymbols[randIdx-1]
        this.ShowById(randVal,coin)
        this.setMaskVisible(true)
    },

    //显示随机符号
    ShowRandomBonusSymbol:function(reelIndex, isNoBonus){
        let randMult = [0.5,1,2,3,4,10,20];
        let multIndex = Global.random(1,randMult.length)
        let mult = randMult[multIndex-1]
        let coin = cc.vv.gameData.GetTotalBet()*mult

        let cfg = cc.vv.gameData.getGameCfg()
        let randomBonus = isNoBonus ? cfg.randomNoBonusSymbols :cfg.randomBonusSymbols
        let randIdx = Global.random(1,randomBonus[reelIndex].length)
        let randVal = randomBonus[reelIndex][randIdx-1]
        this.ShowById(randVal,coin)

    },

    //显示symbole
    //id:物品id
    //data:额外传递的数据
    ShowById:function(id,data){  //已重写
        this._id = id
        this._data = data
        this._state = "normal";

        if(this._showNode){
            this._showNode.active = false
        }
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].node){
            this._showNode = cc.find(cfg.symbol[id].node,this.node)
            this._showNode.color = cc.Color.WHITE;
            this._showNode.active = true
            if(cfg.symbol[this._id].mult){
                cc.find("s24",this.node).active = false
                cc.find("s25",this.node).active = false
                cc.find("s26",this.node).active = false
                cc.find("s27",this.node).active = false
                cc.find("s28",this.node).active = false
                let node = cc.find(cfg.symbol[this._id].dataNode,this.node)
                node.active = true
                let jp = cc.find("jp",node)
                if(jp){
                    jp.active = true
                }
                let multNode = cc.find("mult",node)
                if(multNode){
                    multNode.active = false
                    cc.find("s_2x",multNode).active = false
                    cc.find("s_3x",multNode).active = false
                    cc.find("s_4x",multNode).active = false
                }
            }else{
                cc.find("s24",this.node).active = false
                cc.find("s25",this.node).active = false
                cc.find("s26",this.node).active = false
                cc.find("s27",this.node).active = false
                cc.find("s28",this.node).active = false
            }
        }
        else{
            console.log(">>>> 未找到配置id:" + id)
        }
        let coinLable =  cc.find("coin", this.node)
        if(cfg.symbol[id].coin){
            coinLable.active = true
            coinLable.getComponent(cc.Label).string = Global.convertNumToShort(this._data,1000,0,null,1000); 
        }else{
            coinLable.active = false
        }
    },

    SetCoin(coin){
        this._data = coin
        let cfg = cc.vv.gameData.getGameCfg()
        let coinLable =  cc.find("coin", this.node)
        if(cfg.symbol[this._id].coin){
            coinLable.active = true
            coinLable.getComponent(cc.Label).string = Global.convertNumToShort(this._data,1000,0,null,1000); 
        }else{
            coinLable.active = false
        }
    },

    setMult(mult){
        if(mult === 2 || mult === 3 || mult === 4){
            let cfg = cc.vv.gameData.getGameCfg()
            if(cfg.symbol[this._id].mult){
                cc.find("s24",this.node).active = false
                cc.find("s25",this.node).active = false
                cc.find("s26",this.node).active = false
                cc.find("s27",this.node).active = false
                cc.find("s28",this.node).active = false
                let node = cc.find(cfg.symbol[this._id].dataNode,this.node)
                if(node){
                    node.active = true
                    let jp = cc.find("jp",node)
                    if(jp){
                        jp.active = false
                    }
                    let multNode = cc.find("mult",node)
                    if(multNode){
                        multNode.active = true
                        cc.find("s_"+mult+"x",multNode).active = true
                    }
                }
            }
        }
    },

    setMaskVisible(isMask) {
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[this._id] && cfg.symbol[this._id].node && cfg.symbol[this._id].isMask){
            let showNode = cc.find(cfg.symbol[this._id].node,this.node)
            if (isMask) {
                showNode.color = new cc.Color(120, 120, 120);
            }
            else {
                showNode.color = cc.Color.WHITE;
            }
        }
    },

    setBonusMaskVisible(isMask) {
        this.node.children.forEach(node=>{
            if (isMask) {
                node.color = new cc.Color(120, 120, 120);
                if(node.active && (node.name == "s24" || node.name == "s25" || node.name == "s26" || node.name == "s27" || node.name == "s28")){
                    cc.find("jp",node).color = new cc.Color(120, 120, 120);
                    cc.find("mult",node).color = new cc.Color(120, 120, 120);
                    cc.find("mult",node).children.forEach(node2=>{
                        node2.color = new cc.Color(120, 120, 120);
                    })
                }
            }
            else {
                node.color = cc.Color.WHITE;
            }
        })
    },

    StopMoveEnd(){
        this._super()
        this.playidleAnimation()
    },

    // update (dt) {},


    BonusStopMove(){  
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = false
            let aniNode = this.setBonusAnimationToTop(true)
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true

            if(cfg.symbol[id].stop_ani && cfg.symbol[id].stop_ani.name != ""){
                this.node.zIndex = cfg.symbol[id].stop_ani.zIndex - this._bonusIndex  + this._reelIdx*10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].stop_ani.name,false)
                    if(cfg.symbol[id].idle_ani){
                        nodeSp.setCompleteListener(()=>{
                            nodeSp.setCompleteListener(null)
                            this.playBonusIdleAnimation()
                        });
                    }
                }
            }
        }
        return isPlay
    },

    //开始旋转时刻
    bonusStartMove:function(){
        this.node.zIndex = 50 - this._bonusIndex  + this._reelIdx*10;
        this.node.active = true
        if(this._showNode){
            this._showNode.active = true
        }
    },

    //待机动画
    playBonusIdleAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].idle_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true
            let aniNode = this.setBonusAnimationToTop(true)
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true

            if(cfg.symbol[id].idle_ani && cfg.symbol[id].idle_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].idle_ani.zIndex - this._bonusIndex + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].idle_ani.name,true)
                }
            }
        }
        return isPlay
    },

    //在顶层播放动画；能覆盖左右两列
    setBonusAnimationToTop(isTop){
        if(this._topAniNode){
            if (isTop) {
                let cloneNode = cc.find(cc.js.formatStr("symbol_ani_%s_%s",this._bonusIndex,this._reelIdx),this._topAniNode);
                if (!cloneNode) {
                    cloneNode = cc.instantiate(this.node)
                }
                let wordPos = this.node.convertToWorldSpaceAR(cc.v2(0.0));
                cloneNode.parent = this._topAniNode
                cloneNode.name = cc.js.formatStr("symbol_ani_%s_%s",this._bonusIndex,this._reelIdx)
                cloneNode.position = this._topAniNode.convertToNodeSpaceAR(wordPos)
                this.node.active = false
                return cloneNode
            }else{
                let showNode = cc.find(cc.js.formatStr("symbol_ani_%s_%s",this._bonusIndex,this._reelIdx),this._topAniNode);
                if (showNode) {
                    showNode.removeFromParent()
                    showNode.destroy()
                }
                this.node.active = true
                if(this._showNode){
                    this._showNode.active = true
                }
            } 
        }
        return this.node
    },

    SetSymbolIdx:function(idx){
        this._symbolIdx = idx;
        if(this._id === 2){
            this.node.zIndex = 150 - idx;
        }else{
            this.node.zIndex = 100 - idx;
        }
    },
});
