/**
 * slots 控制部分
 */
let TypeID = [21, 28, 27, 26, 24, 25, 23, 22]   //0: 金币  1：mini 2:minor 3:major 4:grand 5:max 6：mul 7：addrow 
cc.Class({
    extends: require("LMSlots_Slots_Base"),
    properties: {
        _isSuperBonus: false,
        _canStopSlots: false,
        _prizePool: [],
    },

    //初始化
    Init: function () {
        let prizePool = cc.find("LMSlots_PrizePool_1", this.node.parent)
        for (let i = 0; i < prizePool.children.length; i++) {
            const element = prizePool.children[i];
            let script = element.getComponent("LMSlotMachine_PrizePool")
            this._prizePool[script.dataType] = script
        }
        this._super()
        this.playMedusaAnimation(1)
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

    //创建卷轴
    createReels: function (col, row) {
        let reelCmp = this._cfg.scripts.Reels
        for (let i = 0; i < col; i++) {
            let node = cc.find("reels/reel" + (i + 1), this.node)
            let scp = node.addComponent(reelCmp)
            //第一列和最后一列只有三个图标；
            if (i == 0 || i == 4) {
                scp.Init(i, row - 1, this._topAniNode)
            } else {
                scp.Init(i, row, this._topAniNode)
            }

            this._reels.push(scp)

        }
    },

    //点击旋转按钮调用
    StartMove: function () {
        this._super()
        Global.SlotsSoundMgr.playNormalBgm()
        Global.NmedusaGameControl.superFreeGameWild.show()
        if (!this._isSuperBonus) {
            Global.NmedusaGameControl.superFreeGameWild.clearWild()
        }
        this._canStopSlots = false
    },

    async onMsgSpine(msg) {
        this._super(msg)
        //触发免费
        if (this._gameInfo.freeResult && this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.idxs) {
            this.playActive(true)
        }
        //触发bonus游戏
        if (this._gameInfo.allBonusData && this._gameInfo.allBonusData.length > 0) {
            this.playActive(true)
        }
        if (cc.vv.gameData.isFreeGame()) {
            if (this._gameInfo.bonusTrail.count === this._gameInfo.bonusTrail.megaIdx[0] ||
                this._gameInfo.bonusTrail.count === this._gameInfo.bonusTrail.megaIdx[1] ||
                this._gameInfo.bonusTrail.count === this._gameInfo.bonusTrail.superBonus[0]) {  //mege Bonus
                await this.playSuperBonusStartAnimation()
                await Global.NmedusaGameControl.superFreeGameWild.showSuperBonus(this._gameInfo.bonusTrail.info.currWildIdxs)
            }
        }
        this._canStopSlots = true
    },

    SetSlotsResult: function (cards) {
        this._gameInfo.roundBonus
        let cardsInfo = []
        for (let i = 0; i < cards.length; i++) {
            let info = {}
            info.id = cards[i]
            info.data = 0
            cardsInfo.push(info)
        }
        let bonusList = [];
        if (Array.isArray(this._gameInfo.roundBonus)) {
            bonusList = this._gameInfo.roundBonus;
        } else if (this._gameInfo.roundBonus && typeof this._gameInfo.roundBonus === "object") {
            bonusList = Object.values(this._gameInfo.roundBonus);
        }
        for (let bonusInfo of bonusList/*this._gameInfo.roundBonus*/) { // By JerryWong
            cardsInfo[bonusInfo.index - 1].data = bonusInfo.coin
            cardsInfo[bonusInfo.index - 1].id = TypeID[bonusInfo.type]
        }

        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for (let i = 0; i < cardsInfo.length; i++) {
            let id = cardsInfo[i].id
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if (this._cfg.symbol[id]) {
                let res = {}
                res.sid = id //符号id
                res.data = cardsInfo[i].data
                if (!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }

        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    ShowWinTrace: function () {
        let allWinIdx = []
        for (let i = 0; i < this._gameInfo.zjLuXian.length; i++) {
            let item = this._gameInfo.zjLuXian[i]
            for (let idx = 0; idx < item.indexs.length; idx++) {
                allWinIdx[item.indexs[idx]] = 1
            }
        }
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if (symbol) {
                symbol.playWinAnimation()
                symbol.ShowKuang()
            }
        }
    },

    async OnSpinEnd() {
        this._bottomScript.ShowBtnsByState("moveing_1")
        Global.NmedusaGameControl.superFreeGameWild.hide()
        //显示中奖路线
        this.ShowWinTrace()
        //显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            await this.ShowWinCoin(nWin, cc.vv.gameData.GetGameTotalFreeWin(), false)
        } else {
            await this.ShowWinCoin(nWin, nWin, true)
        }

        //触发免费
        if (this._gameInfo.freeResult && this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.idxs) {
            this.playActive(false)
            if (this._gameInfo.freeResult.isFreeState) {  //免费中免费
                await this.CheckFreeEnterFreeGame();
            } else {
                await this.CheckEnterFreeGame();
            }
        }
        //触发bonus游戏
        if (this._gameInfo.allBonusData && this._gameInfo.allBonusData.length > 0) {
            this.playActive(false)
            this.PausePrizePool(this._gameInfo.jackpotValues)
            await this.CheckTriggerSubGame();
            let currentCoin = this._bottomScript.getCurrentWin()
            let bonusWinCoin = cc.vv.gameData.getBonusControl().getBonusWinCoin()
            await this.ShowWinCoin(bonusWinCoin, currentCoin, true)
        }
        //触发退出免费
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() == 0) {
            await this.CheckExitFreeGame();
            await this.ShowWinCoin(this._bottomScript.getCurrentWin(), this._bottomScript.getCurrentWin(), true)
        }

        this.CanDoNextRound()
    },


    //showWin
    ShowWinCoin(nAddWin, nTotalWin, bUpdateBalance) {
        return new Promise(async (sucess, failed) => {
            this.ShowBottomWin(nAddWin, nTotalWin, bUpdateBalance, sucess)
        });
    },

    //检查退出免费
    async CheckExitFreeGame() {
        return new Promise(async (sucess, failed) => {
            cc.vv.gameData.setIsFreeGame(false);
            await cc.vv.gameData.getPopControl().showFreeGameWinner(cc.vv.gameData.GetGameTotalFreeWin())
            await cc.vv.gameData.getPopControl().playMedusaAnimation(() => {
                this.playMedusaAnimation(1)
                this.ShowGameview(false)
                Global.NmedusaGameControl.collectBonusControl.showFreeGameCollect(false)
                Global.NmedusaGameControl.superFreeGameWild.clearWild()
                this.Resume()
            });
            Global.SlotsSoundMgr.playNormalBgm(true)
            sucess();
        });
    },

    //检查免费进入免费
    async CheckFreeEnterFreeGame() {
        return new Promise(async (sucess, failed) => {
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bell)
            //触发动画
            for (let id of this._gameInfo.freeResult.freeInfo.idxs) {
                let symbol = this.GetSymbolByIdx(id)
                if (symbol) {
                    symbol.playWinAnimation()
                }
            }
            await this.awaitTime(2.5);
            await cc.vv.gameData.getPopControl().showFreeGameTimes(this._gameInfo.freeResult.freeInfo.freeCnt, 2);
            sucess();
        });
    },

    //检查进入免费
    async CheckEnterFreeGame() {
        return new Promise(async (sucess, failed) => {
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bell)
            //触发动画
            for (let id of this._gameInfo.freeResult.freeInfo.idxs) {
                let symbol = this.GetSymbolByIdx(id)
                if (symbol) {
                    symbol.playWinAnimation()
                }
            }
            Global.NmedusaGameControl.collectBonusControl.activeBonus()
            this.Backup()
            await this.awaitTime(1.5);
            cc.vv.gameData.setIsFreeGame(true);
            let winType = 1
            if (this._gameInfo.bonusTrail.count === this._gameInfo.bonusTrail.megaIdx[0] ||
                this._gameInfo.bonusTrail.count === this._gameInfo.bonusTrail.megaIdx[1] ||
                this._gameInfo.bonusTrail.count === this._gameInfo.bonusTrail.superBonus[0]) {  //mege Bonus
                winType = 3
            }
            await cc.vv.gameData.getPopControl().showFreeGameTimes(this._gameInfo.freeResult.freeInfo.freeCnt, winType);
            await cc.vv.gameData.getPopControl().playMedusaAnimation(() => {
                this.playMedusaAnimation(3)
                Global.NmedusaGameControl.collectBonusControl.showFreeGameCollect(true)
                this.ShowGameview(true)
            });
            Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.free_bgm)
            sucess();
        });
    },

    //是否触发小游戏
    async CheckTriggerSubGame() {
        return new Promise(async (sucess, failed) => {
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bell)
            for (let info of this._gameInfo.roundBonus) {
                let symbol = this.GetSymbolByIdx(info.index)
                if (symbol) {
                    symbol.playTriggerAnimation()
                }
            }
            if (!cc.vv.gameData.isFreeGame()) {
                this._bottomScript.DoHideWinAction()
            }

            await this.awaitTime(1.5);
            cc.vv.gameData.setIsBonusGame(true);
            cc.vv.gameData.getPopControl().playPopBonus();
            await this.awaitTime(4);
            cc.vv.gameData.getPopControl().playSnakeAnimation();
            await this.awaitTime(1);
            cc.vv.gameData.getBonusControl().enterGame(this._gameInfo.allBonusData, sucess, true)
        });
    },

    ShowGameview(bFree) {
        if (bFree) {
            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()

            //显示免费次数
            this._bottomScript.ShowFreeModel(true, total - rest, total)
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            this._bottomScript.SetWin(nTotal)


            //this.CanDoNextRound()

        }
        else {
            this._bottomScript.ShowFreeModel(false)
        }

        let bonusTrail = cc.vv.gameData.getDeskInfo().bonusTrail
        if (this._gameInfo) {
            bonusTrail = this._gameInfo.bonusTrail
        }
        Global.NmedusaGameControl.collectBonusControl.setGameUIVisible(!bFree)

        //可能还需要显示免费背景图
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal")
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free")
        let normalBonus = cc.find("Canvas/safe_node/spr_bg_bonus")
        if (normalFree) { //存在免费游戏背景才执行下面的逻辑
            if (normalBg) {
                normalBg.active = !bFree
            }

            if (bonusTrail.count === bonusTrail.superBonus[0]) { //super Bonus
                normalFree.active = false
                normalBonus.active = bFree
            } else {
                normalFree.active = bFree
                normalBonus.active = false
            }
        }

        if (bFree) {
            if (bonusTrail.count === bonusTrail.superBonus[0]) { //super Bonus
                this._isSuperBonus = true
                if (bFree) {
                    Global.NmedusaGameControl.superFreeGameWild.show()
                    Global.NmedusaGameControl.superFreeGameWild.recaveryWild(bonusTrail.info.wildIdxs)
                }
            } else {
                this._isSuperBonus = false
            }
            if (bonusTrail.count === bonusTrail.megaIdx[0] ||
                bonusTrail.count === bonusTrail.megaIdx[1] ||
                bonusTrail.count === bonusTrail.superBonus[0]) {  //mege Bonus
                this._bottomScript.showTotalBet(false)
            }
        } else {
            this._bottomScript.showTotalBet(true)
        }
    },

    //断线重连的显示
    //可根据自己断线逻辑重写
    async ReconnectShow() {
        this.ShowGameview(cc.vv.gameData.isFreeGame())
        Global.NmedusaGameControl.collectBonusControl.initData()
        Global.NmedusaGameControl.collectBonusControl.showFreeGameCollect(cc.vv.gameData.isFreeGame())
        if (cc.vv.gameData.isFreeGame()) {
            this.playMedusaAnimation(3)
        } else {
            this.playMedusaAnimation(1)
        }
        //是否是bonus游戏
        if (cc.vv.gameData.getDeskInfo().allBonusData && cc.vv.gameData.getDeskInfo().allBonusData.length > 0) {
            this.PausePrizePool(cc.vv.gameData.getDeskInfo().jackpotValues)
            await new Promise(async (sucess, failed) => {
                this._bottomScript.ShowBtnsByState("moveing_1")
                cc.vv.gameData.setIsBonusGame(true);
                cc.vv.gameData.getBonusControl().enterGame(cc.vv.gameData.getDeskInfo().allBonusData, sucess, false)
            });
            let currentCoin = this._bottomScript.getCurrentWin()
            let bonusWinCoin = cc.vv.gameData.getBonusControl().getBonusWinCoin()
            await this.ShowWinCoin(bonusWinCoin, currentCoin, true)
        }

        this.CanDoNextRound()
    },

    playMedusaAnimation(type) {
        let medusaRole = cc.find("Canvas/safe_node/slots/role/spine_role")

        if (type == 1) {  //普通
            let animation = medusaRole.getComponent(sp.Skeleton);
            animation.setAnimation(0, "idle", true)
            // this.scheduleOnce(()=>{
            //     this.playMedusaAnimation(2)
            // },6.6);
        } else if (type == 2) {  //笑
            // let animation = medusaRole.getComponent(sp.Skeleton);
            // animation.setAnimation(0,"idle",false)
            // animation.setCompleteListener(()=>{
            //     this.playMedusaAnimation(1)
            //     animation.setCompleteListener(null)
            // });
        } else if (type == 3) { //免费游戏待机
            let animation = medusaRole.getComponent(sp.Skeleton);
            animation.setAnimation(0, "idle", true)
            this.scheduleOnce(() => {
                this.playMedusaAnimation(4)
            }, 6.6);
        } else if (type == 4) { //免费游戏
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.flash)
            let animation = medusaRole.getComponent(sp.Skeleton);
            animation.setAnimation(0, "skill", false)
            animation.setCompleteListener(() => {
                this.playMedusaAnimation(1)
                animation.setCompleteListener(null)
            });
        }
    },
    playActive(isActive) {
        let bg_mask = cc.find("Canvas/safe_node/spr_bg_mask")
        // let active_spine_1 = cc.find("Canvas/safe_node/active_spine_1")
        let active_spine_2 = cc.find("Canvas/safe_node/active_spine_2")
        if (isActive) {
            // active_spine_1.active = true
            active_spine_2.active = true
            bg_mask.active = true
            bg_mask.runAction(cc.fadeTo(1, 180));
            // let animation_1 = active_spine_1.getComponent(sp.Skeleton);
            // animation_1.setAnimation(0,"animation",true)
            let animation_2 = active_spine_2.getComponent(sp.Skeleton);
            animation_2.setAnimation(0, "animation", true)
        } else {
            // active_spine_1.active = false
            active_spine_2.active = false
            bg_mask.runAction(cc.fadeOut(0.5));
        }
    },

    playSuperBonusStartAnimation() {
        return new Promise((sucess, failed) => {
            this.unscheduleAllCallbacks()
            let medusaRole = cc.find("Canvas/safe_node/slots/role/spine_role")
            let animation = medusaRole.getComponent(sp.Skeleton);
            animation.setAnimation(0, "jineng", false)
            animation.setCompleteListener(() => {
                this.playMedusaAnimation(1)
                animation.setCompleteListener(null)
                sucess()
            })
        })
    },

    CanStopSlot() {
        return this._canStopSlots
    },

    PausePrizePool(jackpotValues) {
        for (let i = 0; i < jackpotValues.length; i++) {
            const element = jackpotValues[i];
            this._prizePool[i].PausePrizePool(element)
        }
    },

    RestPrizePool() {
        for (let i = 0; i < this._prizePool.length; i++) {
            this._prizePool[i].RestPrizePool()
        }
    },
});
