// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html

cc.Class({
    extends: cc.Component,

    properties: {
        _gameUI:null,
        _collectAni:null,
        _itemNode:null,
        _itemList:[],
        _clickButton:null,
        _tips:null,
        _tipsClickButton:null,
        _num:0,
        _needBet:0,
    },

    onLoad () {
        this._gameUI = cc.find("Game_UI",this.node);
        this._collectAni = cc.find("Game_UI/collect_ani",this.node);
        this._itemNode = cc.find("Game_UI/item_node",this.node);
        this._clickButton = cc.find("Game_UI/button",this.node);
        this._tipsClickButton = cc.find("Game_UI/buttonTips",this.node)

        for (let index = 1; index < 17; index++) {
            let item = cc.find("item_"+index,this._itemNode);
            this._itemList.push(item)
        }
        this._tips = cc.find("Game_UI/tips",this.node)
      
        this._clickButton.on("click", ()=>{
            if(cc.vv.gameData.GetSlotState() != 'idle'){
                return
            }
            if(cc.vv.gameData.GetAutoModelTime() > 0){
                return
            }
            if(this._needBet <= cc.vv.gameData._deskInfo.mults.length){
                cc.vv.gameData.GetBottomScript().SetBetIdx(this._needBet)
                this.updataCollectState()
            }
            return true
        });  
        this._tipsClickButton.on("click",()=>{
            let curmult = cc.vv.gameData.GetBetIdx()
            if(curmult >= this._needBet){  //已经解锁
                this.showTips()
            }
        })
    },

    setGameUIVisible(isVisible) {
        this._gameUI.active = isVisible
    },

    initData(){
        this._num = cc.vv.gameData.bonusTrail.count
        this._needBet = cc.vv.gameData._deskInfo.needBet
        for (let index = 0; index < this._num; index++) {
            if (index == 3 || index == 7 || index == 15 ) {
                this._itemList[index].getComponent(sp.Skeleton).setAnimation(0,"animation3",true);
            }else{
                this._itemList[index].getChildByName("icon").active = true
            }
        }

        let currBetIndex = cc.vv.gameData.GetBetIdx()
        if (currBetIndex >= this._needBet) {
            this._isLock = false
            this.playMaskAnimation(1)
        }else{
            this._isLock = true
            this.playMaskAnimation(3)
        }
    },

    showFreeGameCollect(isShow){
        if (isShow) {
            this.playMaskAnimation(4)
            if(this._num === 4 || this._num === 8){
                cc.find("mage",this._collectAni).active = true
                cc.find("super",this._collectAni).active = false
            }else if(this._num === 16){
                cc.find("mage",this._collectAni).active = false
                cc.find("super",this._collectAni).active = true
            }
        }else{
            if(this._num == 16) {
                this.reSetCollect()
            }
            if (this._isLock) {
                this.playMaskAnimation(3)
            }else{
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.shouji_unlock)
                this.playMaskAnimation(1)
            } 
            cc.find("mage",this._collectAni).active = false
            cc.find("super",this._collectAni).active = false
        }
    },

    
    reSetCollect(){
        for (let index = 0; index < 16; index++) {
            if (index == 3 || index == 7 || index == 15 ) {
                this._itemList[index].getComponent(sp.Skeleton).setAnimation(0,"animation1",true);
            }else{
                this._itemList[index].getChildByName("icon").active = false
            }
        }
        this._num = 0
    },

       //1.非触发收集游戏的下注额；不触发收集  在外面判断
    //2.移动火车；且播放对应的音效
    //3.是否打开盒子；播放盒子特效和音效
    //4.激活收集点
    activeBonus(){
        let currBetIndex = cc.vv.gameData.GetBetIdx()
        if (currBetIndex >= this._needBet) {
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.shouji_one)
            this._num++  
            if (this._num == 4 || this._num == 8 || this._num == 16 ) {
                this._itemList[this._num-1].getComponent(sp.Skeleton).setAnimation(0,"animation2",false);
                this._itemList[this._num-1].getComponent(sp.Skeleton).addAnimation(0,"animation3",true);
            }else{
                this._itemList[this._num-1].getChildByName("icon").active = true
            }
        }
    },

    updataCollectState(){
        let currBetIndex = cc.vv.gameData.GetBetIdx()
        if (currBetIndex >= this._needBet) {
            if (this._isLock) {
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.shouji_unlock)
                this.playMaskAnimation(1)
            }
        }else{
            if (!this._isLock) {
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.shouji_lock)
                this.playMaskAnimation(2)
            }
        }
    },

    playMaskAnimation(type){
        let spCollect = this._collectAni.getComponent(sp.Skeleton)
        this._collectAni.active = true
        if (type == 1) {   //解锁动画
            spCollect.setAnimation(0,"animation1",false);
            spCollect.setCompleteListener(null)
            this._isLock = false
            this._clickButton.getComponent(cc.Button).interactable = false
            this._itemNode.active = true
        }else if(type == 2) { //上锁动画
            spCollect.setAnimation(0,"animation2",false);
            spCollect.addAnimation(0,"animation3",true);
            spCollect.setCompleteListener(()=>{
                this._itemNode.active = false
                spCollect.setCompleteListener(null)
            })
            this._isLock = true
            this._clickButton.getComponent(cc.Button).interactable = true
        }else if(type == 3) { //已经锁定普通待机动画
            spCollect.setAnimation(0,"animation3",true);
            spCollect.setCompleteListener(null)
            this._isLock = true
            this._clickButton.getComponent(cc.Button).interactable = true
            this._itemNode.active = false
        }else if(type == 4) { //已经锁定免费待机动画
            spCollect.setAnimation(0,"animation4",true);
            spCollect.setCompleteListener(null)
            this._clickButton.getComponent(cc.Button).interactable = false
            this._itemNode.active = false
        }
    },

    showTips(){
        if(!this._tips.active){
            this._tips.active = true
            this._tips.opacity = 0
            cc.tween(this._tips).to(0.5,{opacity:255}).delay(2).to(0.5,{opacity:0}).delay(1).call(()=>{
                this._tips.active = false
            }).start()
        }
    },
});
