/**
 * 游戏入口，配置加载的组件
 * 挂在Canvas节点上
 */
cc.Class({
    extends: require("LMSlots_Logic_Base"),
    properties: {
        collectBonusControl:{
            default:null,
            visible:false
        },
        superFreeGameWild:{
            default:null,
            visible:false
        },
    },
    //初始化公共组件
    InitCommComponent:function(){
        this._super()  
        let bonus_game = cc.find('safe_node/bonus_game',this.node)
        let script_respin_slots = bonus_game.getComponent("Nmedusa_BonusGame")
        cc.vv.gameData.SetBonusControl(script_respin_slots) 
        let popup = cc.find('safe_node/node_pop_ui',this.node)
        let popupControl = popup.getComponent("Nmedusa_Pop")
        cc.vv.gameData.SetPopControl(popupControl) 
        script_respin_slots.Init()         
        popupControl.Init()

        this.collectBonusControl = cc.find('Canvas/safe_node/Collect_Bonus_UI').getComponent("Nmedusa_CollectBonusControl");
        this.superFreeGameWild = cc.find('Canvas/safe_node/superFreeGameWildRoot').getComponent("Nmedusa_SuperFreeGameWild");
        Global.NmedusaGameControl = this
    },

    onDestroy()
    {
        Global.NmedusaGameControl = null
    },


    // update (dt) {},
});
