/**
 * 符号控制
 */
let distance = 420
cc.Class({
    extends: cc.Component,

    properties: {
        wildLianXian:{
            default:null,
            type:cc.Node
        },
        _wildList:[],
    },

    onLoad(){
        this.hide()
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    show(){
        this.node.active = true
    },

    hide(){
        this.node.active = false
    },

    showWild(index){
        return new Promise((sucess,falied)=>{
            this.wildLianXian.active = true
            let startPos = this.wildLianXian.position
            let col = (index - 1) % cc.vv.gameData._cfg.col 
            let row = cc.vv.gameData._cfg.row - Math.floor((index -1)/cc.vv.gameData._cfg.col) -1
            let wildRoot = this.node.getChildByName("node"+col+"_"+row)
            let finalPosition = wildRoot.position
            let dirVec = finalPosition.sub(startPos);//获得从startPos指向endPos的方向向量
            let comVec = new cc.Vec2(0, -1);//计算夹角的参考方向，这里选择y轴负方向
            let radian = cc.v2(dirVec.x,dirVec.y).signAngle(comVec);//获得带方向的夹角弧度值(参考方向顺时针为正值，逆时针为负值)
            let degree = cc.misc.radiansToDegrees(radian)
            let length = dirVec.mag()
            this.wildLianXian.angle = -degree
            this.wildLianXian.scaleY = length / distance
            let lianxianSp = this.wildLianXian.getComponent(sp.Skeleton)
            lianxianSp.setAnimation(0,"animation",false)
            lianxianSp.setCompleteListener(()=>{
                this.wildLianXian.active = false
                lianxianSp.setCompleteListener(null)
                if(!this._wildList[index]){
                    let wildNode = cc.instantiate(cc.vv.gameData.GetPrefabByName(cc.vv.gameData._cfg.symbolPrefab))
                    this._wildList[index] = wildNode.addComponent(cc.vv.gameData._cfg.scripts.Symbols)
                    wildNode.parent = wildRoot
                    wildNode.position = cc.v2(0,0)
                    this._wildList[index].ShowById(1)
                    this._wildList[index].playTriggerAnimation()
                    sucess()
                }else{
                    this._wildList[index].playTriggerAnimation()
                    sucess()
                }
            })
        })
    },

    clearWild(){
        for (const key in this._wildList) {
            if (this._wildList.hasOwnProperty(key)) {
                const element = this._wildList[key];
                element.node.parent = null
            }
        }
        this._wildList = []
    },

    showSuperBonus(indexs){
        return new Promise(async (sucess,falied)=>{
            for (let i = 0; i < indexs.length; i++) {
                const element = indexs[i];
                await this.showWild(element)
                await this.awaitTime(0.2)
            }
            sucess()
        })
    },

    recaveryWild(indexs){
        this.clearWild()
        for (let i = 0; i < indexs.length; i++) {
            const element = indexs[i];
            let col = (element - 1) % cc.vv.gameData._cfg.col 
            let row = cc.vv.gameData._cfg.row - Math.floor((element -1)/cc.vv.gameData._cfg.col) -1
            let wildRoot = this.node.getChildByName("node"+col+"_"+row)
            if(!this._wildList[element]){
                let wildNode = cc.instantiate(cc.vv.gameData.GetPrefabByName(cc.vv.gameData._cfg.symbolPrefab))
                this._wildList[element] = wildNode.addComponent(cc.vv.gameData._cfg.scripts.Symbols)
                wildNode.parent = wildRoot
                wildNode.position = cc.v2(0,0)
                this._wildList[element].ShowById(1)
            }
        }
    }
});
