/**
 * bonus game
 */
let HolderCount = [3,7,7,7,3];
let TypeID = [21,28,27,26,24,25,23,22]   //0: 金币  1：mini 2:minor 3:major 4:grand 5:max 6：mul 7：addrow 
let UpSpinPosY = [226,333,440,547]
let UpSpinBgPosY = [0,107,214,321]

let RowSpineConfig = {
    [25]:[0,20,15,10],
    [30]:[0,15,12,9],
    [35]:[0,10,8,6],
}
let MultSpineConfig = {
    [21]:"animation1",
    [26]:"animation2",
    [31]:"animation3",
}

cc.Class({
    extends: cc.Component,

    properties: {
        effectNode: {
            default: null,      
            type: cc.Node, 
        },
        effectNodeInside: {
            default: null,      
            type: cc.Node, 
        },

        _gameUI:null,
        _slotsUI:null,

        _topScript:null,    //上面的脚本
        _bottomScript:null, //下面的脚本
        _col:0,     //列
        _row:0,     //行
        _reels:[],   //卷轴脚本对象
        _cfg:null,
        _stopTime:null, //停止时间
        _bonusData:null, //每一轮的游戏数据

        _finishBonusData:[], //当前奖励
        _exitCallBack: null,
        _bonusWinCoin: 0,
    },


    //初始化
    Init(){
        this._gameUI = cc.find("game_ui", this.node)
        this._gameUI.active = false;
        this._slotsUI = cc.find("game_ui/slots", this.node)
        this._topAnimationNode = cc.find("top_ani", this._slotsUI)
        this._spinNumLable = cc.find("reels_frame/spine_node/spin/spin", this._slotsUI)
        this._lastSpinNumLable = cc.find("reels_frame/spine_node/spin/last_spin", this._slotsUI)

        this._respinMultActive = cc.find("reels_frame/respin_ban_1/wins_node", this._slotsUI)
        this._respinRespinNode = cc.find("reels_frame/respin_ban_1/wins_node/respin_node", this._slotsUI)
        this._respinRespinX = cc.find("reels_frame/respin_ban_1/wins_node/respin_x", this._slotsUI)

        this._respinRowActive = cc.find("reels_frame/respin_ban_2/activet_node", this._slotsUI)
        this._respinRowNode = cc.find("reels_frame/respin_ban_2/activet_node/respin_node", this._slotsUI)
        this._respinRowspnX = cc.find("reels_frame/respin_ban_2/activet_node/respin_r", this._slotsUI)

        this._spinUpNode = cc.find("reels_frame/spine_node", this._slotsUI)
        this._spinUpBg = cc.find("reels_frame/spine_bg/bg", this._slotsUI)

        this._respin_ban_1 = cc.find("reels_frame/respin_ban_1", this._slotsUI)
        this._respin_ban_2 = cc.find("reels_frame/respin_ban_2", this._slotsUI)

        this._bonusBg = cc.find("Canvas/safe_node/spr_bg_bonus")
    
        this._topScript = cc.vv.gameData.GetTopScript()
        this._bottomScript = cc.vv.gameData.GetBottomScript()
        this._cfg = cc.vv.gameData.getGameCfg()
        this._col = 5
        this._row = 7

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA,this.onRecvGameAction,this);   
        this.createReels(this._col)  

        //this.enterGame()
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    onDestroy()
    {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA,this.onRecvGameAction,false,this);
    },


    async enterGame (data, exitCallBack, isFrist) {
        this._exitCallBack = exitCallBack;
        cc.vv.gameData.GetSlotsScript().node.active = false
        Global.NmedusaGameControl.collectBonusControl.setGameUIVisible(false)
        this._bonusBg.active = true
        this._gameUI.active = true;
        
        this.initData(data);
        // if (isFrist) {
        //     await this.awaitTime(2);
        //     cc.vv.gameData.getPopControl().playPopBonus();
        //     await this.awaitTime(4);
        // }
        Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.respin_bgm)
        await this.updateActive()
        this._bottomScript.ShowBtnsByState("moveing_1")
        this.sendSpinMsg()
    },

    exitGame(){
        if (cc.vv.gameData.isFreeGame()) {
            Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.free_bgm)
        }else{
            Global.SlotsSoundMgr.playNormalBgm(true)
        }
        cc.vv.gameData.GetSlotsScript().node.active = true
        if(cc.vv.gameData.isFreeGame()){    // 免费
            Global.NmedusaGameControl.collectBonusControl.setGameUIVisible(false)
        } else {
            Global.NmedusaGameControl.collectBonusControl.setGameUIVisible(true)
        }
        this._bonusBg.active = false
        this._gameUI.active = false;
        this._topAnimationNode.removeAllChildren()
        cc.vv.gameData.setIsBonusGame(false);
        cc.vv.gameData.GetSlotsScript().RestPrizePool()
    },

    getBonusWinCoin(){
        return this._bonusWinCoin
    },

    initData(data){
        this._bonusWinCoin = 0
        this._finishBonusData = data
        this._spinUpNode.setPosition(cc.v2(0, UpSpinPosY[0]));
        this._spinUpBg.setPosition(cc.v2(0, UpSpinBgPosY[0]));
        this._respinRespinNode.active = true
        this._respinRespinX.active = false
        this._respinRowNode.active = true
        this._respinRowspnX.active = false
        this._respin_ban_1.active = true
        this._respin_ban_2.active = true
        let fb = []
        if (Array.isArray(this._finishBonusData)) { fb = this._finishBonusData}
        for (let bonusData of fb/*this._finishBonusData*/) {
            let bd = []
            if (Array.isArray(bonusData.reelData)) { bd = bonusData.reelData }
            for (let reelData of bd/*bonusData.reelData*/) {
                let row = this._row - Math.floor((reelData.index-1) / this._col) - 1
                let col = (reelData.index-1) % this._col
                let reel = this._reels[col]
                let symbol = reel.GetSymbolByRow(row)
                if(symbol){
                    symbol.ShowById(TypeID[reelData.type],reelData.coin)
                    symbol.playBonusIdleAnimation()
                }
            }
            this._bonusData = bonusData
        } 
        this.updateSpinsNum(this._bonusData.resSpin)
    },

    //首次进入游戏更新 row和mult
    async updateActive(){
        return new Promise(async (sucess, failed)=>{
            let multIndexs = []
            let rowIndexs = []
            let multNum = 0
            let rowNum = 0
            let isHave = false
            if(this._finishBonusData.length === 1){  //第一次进入
                let bonusData = this._finishBonusData[0]
                if (bonusData.mult.length > 0) {
                    multIndexs = bonusData.mult
                    isHave = true
                }
                if (bonusData.row.length > 0) {
                    rowIndexs = bonusData.row
                    isHave = true
                }
                multNum = bonusData.addMult
                rowNum = bonusData.addRow 
                for (let i = multIndexs.length - 1; i >= 0; i--) {
                    let multIndex = multIndexs[i]
                    await this.updateMult(multNum - i,[multIndex])
                }
                for (let i = rowIndexs.length - 1; i >= 0; i--) {
                    let rowIndex = rowIndexs[i]
                    await this.updateRows(rowNum - i,[rowIndex])
                }
            }else{  //恢复对局
                let fbd = []
                if (Array.isArray(this._finishBonusData)) { fbd = this._finishBonusData }
                for (let bonusData of fbd/*this._finishBonusData*/) {
                    if (bonusData.mult.length > 0) {
                        multIndexs = bonusData.mult
                        isHave = true
                    }
                    if (bonusData.row.length > 0) {
                        rowIndexs = bonusData.row
                        isHave = true
                    }
                    multNum = bonusData.addMult
                    rowNum = bonusData.addRow 
                }
                this.initMult(multNum)
                this.initRows(rowNum)
            }

            
            if (isHave) {
                await this.awaitTime(2)
            }
            sucess()
       });  
    },

    //创建卷轴
    createReels:function(col){
        for (let i = 0; i < col; i++) {
            let node = cc.find("reels/reel" + (i+1),this._slotsUI)
            let scp = node.addComponent("Nmedusa_BonusReel")
            scp.Init(i,1,HolderCount[i],this._topAnimationNode)
            this._reels.push(scp)
        }
    },

    //更新次数
    updateSpinsNum(num){
        if(num > 0){
            this._lastSpinNumLable.active = false
            this._spinNumLable.active = true
            let atlas = cc.vv.gameData.GetAtlasByName("base")
            cc.find("num",this._spinNumLable).getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme191_r_" + num)
            if(num == 3){
                let liziSpine = cc.find("cssx", this._spinUpNode)
                liziSpine.active = true;
                let animation = liziSpine.getComponent(sp.Skeleton);
                animation.setAnimation(0,"animation",false)
                animation.setCompleteListener(()=>{
                    liziSpine.active = false;
                });
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.add_spin)
            }
        }else if(num == 0){
            this._lastSpinNumLable.active = true
            this._spinNumLable.active = false
        }else{
            this._lastSpinNumLable.active = false
            this._spinNumLable.active = false
        }
    },

    //增加Mult
    async updateMult(num, indexs){
        return new Promise(async (sucess, failed)=>{
            let atlas = cc.vv.gameData.GetAtlasByName("base")
            let idx = []
            if (Array.isArray(indexs)) { idx = indexs}
            for (let idx of idx/*indexs*/) {
                let liziSpine = cc.find("lizi_mult_spine_" + idx, this.effectNodeInside)
                liziSpine.active = true;
                let animation = liziSpine.getComponent(sp.Skeleton);
                animation.setAnimation(0,MultSpineConfig[idx],false)
                animation.setCompleteListener(()=>{
                    liziSpine.active = false;
                });
            }
            
            if (indexs.length > 0) {
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.fly_mul)
                await this.awaitTime(1);
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.number)
                this._respinMultActive.runAction(cc.sequence(cc.scaleTo(0.3,0.1),cc.callFunc(()=>{
                    this._respinRespinNode.active = false
                    this._respinRespinX.active = true
                    this._respinRespinX.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme191_respin_" + num + "x")
                }),cc.scaleTo(0.3,1)));
                await this.awaitTime(0.6);
            }
            sucess()
       });  
    },

    initMult(num){
        if(num<=0) return
        let atlas = cc.vv.gameData.GetAtlasByName("base")
        this._respinRespinNode.active = false
        this._respinRespinX.active = true
        this._respinRespinX.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme191_respin_" + num + "x")
    },

    //增加row
    updateRows(num, indexs){
        return new Promise(async (sucess, failed)=>{
            let atlas = cc.vv.gameData.GetAtlasByName("base")
            let idx = indexs[0]
            await new Promise((suc,fail)=>{
                let liziSpine = cc.find("lizi_row_spine_" + idx + "_" + num, this.effectNodeInside)
                // liziSpine.setRotation(-RowSpineConfig[idx][num])
                liziSpine.active = true;
                let animation = liziSpine.getComponent(sp.Skeleton);
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.fly_row)
                animation.setAnimation(0,"animation1",false)
                animation.setCompleteListener(()=>{
                    liziSpine.active = false;
                    animation.setCompleteListener(null)
                    suc()
                })
            })

            if (indexs.length > 0) {
                let activeSpine = cc.find("reels_frame/spine_node/active", this._slotsUI)
                activeSpine.active = true;
                let animation = activeSpine.getComponent(sp.Skeleton);
                animation.setAnimation(0,"animation",false)
                animation.setCompleteListener(()=>{
                    activeSpine.active = false;
                });
                await this.awaitTime(0.5);
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.add_row)
                this._spinUpNode.runAction(cc.moveTo(0.5,cc.v2(0,UpSpinPosY[num])))
                this._spinUpBg.runAction(cc.moveTo(0.5,cc.v2(0,UpSpinBgPosY[num])))
                await this.awaitTime(0.8);
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.number)
                this._respinRowActive.runAction(cc.sequence(cc.scaleTo(0.3,0.1),cc.callFunc(()=>{
                    this._respinRowNode.active = false
                    this._respinRowspnX.active = true
                    this._respinRowspnX.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme191_respin_r" + num)
                }),cc.scaleTo(0.3,1)));
            }
            sucess()
       });  
    },

    initRows(num){
        if(num<=0) return
        let atlas = cc.vv.gameData.GetAtlasByName("base")
        this._respinRowNode.active = false
        this._respinRowspnX.active = true
        this._respinRowspnX.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme191_respin_r" + num)
        this._spinUpNode.y = UpSpinPosY[num]
        this._spinUpBg.y = UpSpinBgPosY[num]
    },

    //bonus结算动画
    async showEndAnimation(){
        return new Promise(async (sucess, failed)=>{
            let bonusInfo = this._finishBonusData[this._finishBonusData.length-1]
            this._respin_ban_1.active = false
            this._respin_ban_2.active = false
            this.updateSpinsNum(-1)
            if (bonusInfo.addMult > 1) {
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bigmul)
                let spineNode = cc.find("mult_and_spine", this.effectNodeInside)
                spineNode.active = true;
                let animation = spineNode.getComponent(sp.Skeleton);
                animation.setAnimation(0,"animation"+bonusInfo.addMult,false)
                animation.setCompleteListener(()=>{
                    spineNode.active = false;
                });
                await this.awaitTime(3)
                let fb = []
                if (Array.isArray(this._finishBonusData)) { fb = this._finishBonusData }
                for (let bonusData of fb/*this._finishBonusData*/) {
                    let bd = []
                    if (Array.isArray(bonusData.reelData)) { bd = bonusData.reelData }
                    for (let reelData of bd/*bonusData.reelData*/) {
                        let row = this._row - Math.floor((reelData.index-1) / this._col) - 1
                        let col = (reelData.index-1) % this._col
                        let symbol = this.getSymbolTopAni(row,col)
                        if (symbol) {
                            if (col > 0 && col < 4) {
                                reelData.coin = reelData.coin*bonusInfo.addMult
                                let showNode = cc.find(cc.js.formatStr("fb_%s_%s",row,col),this.effectNodeInside);
                                if(showNode){ 
                                    showNode.active = true
                                    let showNodeAnimation = showNode.getComponent(sp.Skeleton);
                                    showNodeAnimation.setAnimation(0,"animation",false)
                                    showNodeAnimation.setCompleteListener(()=>{
                                        showNodeAnimation.setCompleteListener(null)
                                        showNode.active = false;
                                    });
                                }
                                symbol.SetCoin(reelData.coin)
                                symbol.setMult(bonusInfo.addMult)
                            }else{
                                symbol.ShowById(TypeID[reelData.type],reelData.coin)
                            }  
                        }
                    }
                }
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.mul_symbol)
                await this.awaitTime(1)
            }
            sucess()
       });  
    },

    //bonus游戏结算
    async settlement(){
        return new Promise(async (sucess, failed)=>{
            let tempBonusData = []
            let fbd = []
            if (Array.isArray(this._finishBonusData)) { fbd = this._finishBonusData }
            for (let bonusData of fbd/*this._finishBonusData*/) {
                let bd = []
                if (Array.isArray(bonusData.reelData)) { bd = bonusData.reelData}
                for (let reelData of bd/*bonusData.reelData*/) {
                    let col = (reelData.index-1) % this._col
                    if (col > 0 && col < 4) {
                        tempBonusData.push(reelData)
                    }  
                }
            }
            tempBonusData.sort((a, b)=>{
                let row_a = this._row - Math.floor((a.index-1) / this._col) - 1
                let col_a = (a.index-1) % this._col
                let row_b = this._row - Math.floor((b.index-1) / this._col) - 1
                let col_b = (b.index-1) % this._col
                if (col_a == col_b) {
                    return row_b - row_a;
                }else{
                    return col_a - col_b;
                }
            });
            let bonusInfo = this._finishBonusData[this._finishBonusData.length-1]
            let td = []
            if (Array.isArray(tempBonusData)) { td = tempBonusData}
            for (let reelData of td/*tempBonusData*/) {
                let row = this._row - Math.floor((reelData.index-1) / this._col) - 1
                let col = (reelData.index-1) % this._col
                let symbol = this.getSymbolTopAni(row,col)
                if (symbol) {
                    symbol.ShowById(TypeID[reelData.type],reelData.coin)
                    symbol.setMult(bonusInfo.addMult)
                    symbol.setBonusMaskVisible(true)
                }
                this.playBaoAnimation(row,col)
                if(reelData.type >=1 && reelData.type <= 5){  //中jakepot
                    await cc.vv.gameData.getPopControl().showJackpotWinCoin(reelData.type,bonusInfo.addMult,reelData.coin)
                }else{
                    await this.playCollectAnimation(row,col)
                }
                let currentCoin = this._bottomScript.getCurrentWin()
                this._bottomScript.ShowWin(currentCoin + reelData.coin,0.8,null,null)
                this.playBoomAnimation()
                await this.awaitTime(1.8)
            }
            sucess()
       });  
    },

    playCollectAnimation:function(nRow,nCol){
        return new Promise(async (sucess, failed)=>{
            let showNode = cc.find(cc.js.formatStr("sj_%s_%s",nRow,nCol),this.effectNode);
            if(showNode){ 
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.collect)
                showNode.active = true
                let endPos = this.effectNode.convertToNodeSpaceAR(cc.vv.gameData.GetBottomScript().getWinLabelNor().convertToWorldSpaceAR(cc.v2(0,0)))
                let offX = endPos.x;
                cc.tween(showNode).by(0.5, {x:offX}).start();
                let animation = showNode.getComponent(sp.Skeleton);
                animation.setCompleteListener(()=>{
                    animation.setCompleteListener(null)
                    showNode.x -= offX;
                    showNode.active = false;
                    sucess()
                });
            }else{
                sucess()
            }
       });  
    },
    playBoomAnimation:function(){
        let showNode = cc.find("boom",this.effectNode);
        if(showNode){ 
            showNode.active = true
            let endPos = this.effectNode.convertToNodeSpaceAR(cc.vv.gameData.GetBottomScript().getWinLabelNor().convertToWorldSpaceAR(cc.v2(0,0)))
            showNode.position = endPos;
            let animation = showNode.getComponent(sp.Skeleton);
            animation.setCompleteListener(()=>{
                animation.setCompleteListener(null)
                showNode.active = false;
            });
        }
    },
    
    playBaoAnimation:function(nRow,nCol){
        let showNode = cc.find("bonus_bao",this.effectNodeInside);
        if(showNode){ 
            showNode.active = true
            let reel = this._reels[nCol]
            let symbol = reel.GetSymbolByRow(nRow)
            if(symbol){
                let wordPos = symbol.node.convertToWorldSpaceAR(cc.v2(0.0));
                showNode.position = this.effectNodeInside.convertToNodeSpaceAR(wordPos)
            }
            let animation = showNode.getComponent(sp.Skeleton);
            animation.setCompleteListener(()=>{
                animation.setCompleteListener(null)
                showNode.active = false;
            });
        }
    },
    

    //点击旋转按钮调用
    StartMove(){
        this._bonusData = null
        this.MoveReels(this._reels)
        this._stopTime = this._cfg.auto_stop_time
    },

    sendSpinMsg(){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.uid = Global.playerData.uid;
        req.gameid = cc.vv.gameData._gameId;
        req.data = {};
        req.data.rtype = 1;
        cc.vv.NetManager.send(req);
        this.updateSpinsNum(this._bonusData.resSpin-1)
        this.StartMove()
    },

    //收到子游戏操作
    async onRecvGameAction(msg){
        if(msg.code == 200){
            if(msg.data.rtype == 1){   
                this._bonusWinCoin = msg.data.winCoin
                this._bonusData = msg.data.bonusData
                this._finishBonusData.push(this._bonusData)
                this._bottomScript.ShowBtnsByState("moveing_2")
                let reelData = this.creatReelData(this._bonusData.reelData)
                this.SetSlotsResult(reelData)
                if(!cc.vv.gameData.isFreeGame()){
                    cc.vv.gameData.AddCoin(this._bonusWinCoin)
                }
            }
        }
    },

    MoveReels(arry){
        this.moveReelLastIdx = -1
        for(let i = 0; i < arry.length; i++){
            let item = arry[i]
            item.StartMove()
            let idx = item.GetReelIdx()
            if(idx> this.moveReelLastIdx){
                this.moveReelLastIdx = idx
            }  
        }
    },

    //点击停止按钮调用
    StopMove:function(){
        this._stopTime = -1
        this._bottomScript.ShowBtnsByState("moveing_1")
        for(let i = 0; i < this._reels.length; i++ ){
            let item = this._reels[i]
            item.stopRightNow()
        }
    },

    //生成客户端卷轴数据
    creatReelData:function(resultData){
        let reelData = []
        for (let index = 0; index < 35; index++) {
            let info = {}
            info.sid = 0
            info.coin = 0
            reelData.push(info)            
        }
        let rd = []
        if (Array.isArray(resultData)) {
            rd = resultData
        }
        for (let info of rd/*resultData*/) {
            reelData[info.index-1].sid = TypeID[info.type]
            reelData[info.index-1].coin = info.coin
        }
        return reelData
    },

    SetSlotsResult:function(reelData){
        //把结果按卷轴结果整理
        let acRow = reelData.length / this._col
        let reelResults = []
        for(let i = 0;i < reelData.length; i++){
            let col = i % this._col
            let res = {}
            res.sid = reelData[i].sid //符号id
            res.coin = reelData[i].coin
            if(!reelResults[col]) reelResults[col] = []
            reelResults[col].unshift(res)   
        }
        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },


    //全部列都停止了
    //处理停下后的中奖情况，这里多数情况需要根据自己的逻辑来处理
    async OnSpinEnd(){
        this._bottomScript.ShowBtnsByState("moveing_1")
        let multIndexs = []
        let rowIndexs = []
        if (this._bonusData.mult.length > 0) {
            multIndexs = this._bonusData.mult
        }
        if (this._bonusData.row.length > 0) {
            rowIndexs = this._bonusData.row
        }
        this.updateSpinsNum(this._bonusData.resSpin)
        // await this.updateMult(this._bonusData.addMult,multIndexs)
        // await this.updateRows(this._bonusData.addRow,rowIndexs)
        for (let i = multIndexs.length - 1; i >= 0; i--) {
            let multIndex = multIndexs[i]
            await this.updateMult(this._bonusData.addMult - i,[multIndex])
        }
        for (let i = rowIndexs.length - 1; i >= 0; i--) {
            let rowIndex = rowIndexs[i]
            await this.updateRows(this._bonusData.addRow - i,[rowIndex])
        }
        if (this._bonusData.isEnd) {
            await this.showEndAnimation()
            await this.settlement()
            cc.vv.gameData.getPopControl().playSnakeAnimation();
            await this.awaitTime(1);
            this.exitGame()
            await this.awaitTime(2)
            if (this._exitCallBack) {
                this._exitCallBack(); 
            }
        }else{
            this.scheduleOnce(()=>{
                this.sendSpinMsg() 
            },1);
        }   
    },

    
    getSymbolTopAni:function(nRow,nCol){
        let cfg = cc.vv.gameData.getGameCfg()
        let symScp = cfg.scripts.Symbols
        let showNode = cc.find(cc.js.formatStr("symbol_ani_%s_%s",nRow,nCol),this._topAnimationNode);
        if(showNode){ 
            showNode.active = true
            return showNode.getComponent(symScp)
        }
        return null
    },

    //每列停止时间间隔
    //reelIdx:0开始
    GetReelStopInter:function(reelIdx){
        let nIter = this._cfg.reelStopInter || 0.6
        return reelIdx*nIter
    },

    //获取最后一个停下来的列序号
    GetLastStopReelIdx:function(){
        return this.moveReelLastIdx
    },

    update (dt) {
        if(this._stopTime > 0){
            this._stopTime = this._stopTime - dt
            if(this._stopTime <= 0){
                for(let i = 0; i < this._reels.length; i++ ){
                    let item = this._reels[i]
                    let reelStopInterv = this.GetReelStopInter(i)
                    item.StopMove(reelStopInterv)
                }
            }
        }

    },
});
